/*
 * atg_kc705_mig: The KC705 memory: MIG 7 Series DDR3 (1 GB, 64 bit, AXI4
 * 512 bit, ui_clk 200 MHz, regenerated by TCL, design §4.1) behind an AXI4
 * slave in gclk (the clock crossing to ui_clk is inside: MIG's AXI clock
 * converter or an AXI clock converter IP, chosen in p012).
 *
 * WS288 p023 stub: ports and parameters only, every output is 0.
 * The behaviour is specified in spec/boards/kc705/lib/atg_kc705_mig.md.
 */

`timescale 1ns / 1ps
`default_nettype none

module atg_kc705_mig (
	input wire clk,
	input wire rst_n,
	input wire sys_clk,
	input wire sys_rst_n,
	output wire mem_ready,
	/* AXI4 slave (gclk), atg_top's m_* */
	input wire [31:0] s_awaddr,
	input wire [7:0] s_awlen,
	input wire [2:0] s_awsize,
	input wire [1:0] s_awburst,
	input wire [3:0] s_awcache,
	input wire [2:0] s_awprot,
	input wire s_awvalid,
	output wire s_awready,
	input wire [511:0] s_wdata,
	input wire [63:0] s_wstrb,
	input wire s_wlast,
	input wire s_wvalid,
	output wire s_wready,
	output wire [1:0] s_bresp,
	output wire s_bvalid,
	input wire s_bready,
	input wire [31:0] s_araddr,
	input wire [7:0] s_arlen,
	input wire [2:0] s_arsize,
	input wire [1:0] s_arburst,
	input wire [3:0] s_arcache,
	input wire [2:0] s_arprot,
	input wire s_arvalid,
	output wire s_arready,
	output wire [511:0] s_rdata,
	output wire [1:0] s_rresp,
	output wire s_rlast,
	output wire s_rvalid,
	input wire s_rready,
	/* DDR3 pins */
	inout wire [63:0] ddr3_dq,
	inout wire [7:0] ddr3_dqs_p,
	inout wire [7:0] ddr3_dqs_n,
	output wire [13:0] ddr3_addr,
	output wire [2:0] ddr3_ba,
	output wire ddr3_ras_n,
	output wire ddr3_cas_n,
	output wire ddr3_we_n,
	output wire ddr3_reset_n,
	output wire ddr3_ck_p,
	output wire ddr3_ck_n,
	output wire ddr3_cke,
	output wire ddr3_cs_n,
	output wire [7:0] ddr3_dm,
	output wire ddr3_odt
);
	/* spec/boards/kc705/lib/atg_kc705_mig.md */
	assign mem_ready = 1'd0;
	assign s_awready = 1'd0;
	assign s_wready = 1'd0;
	assign s_bresp = 2'd0;
	assign s_bvalid = 1'd0;
	assign s_arready = 1'd0;
	assign s_rdata = 512'd0;
	assign s_rresp = 2'd0;
	assign s_rlast = 1'd0;
	assign s_rvalid = 1'd0;
	assign ddr3_addr = 14'd0;
	assign ddr3_ba = 3'd0;
	assign ddr3_ras_n = 1'd0;
	assign ddr3_cas_n = 1'd0;
	assign ddr3_we_n = 1'd0;
	assign ddr3_reset_n = 1'd0;
	assign ddr3_ck_p = 1'd0;
	assign ddr3_ck_n = 1'd0;
	assign ddr3_cke = 1'd0;
	assign ddr3_cs_n = 1'd0;
	assign ddr3_dm = 8'd0;
	assign ddr3_odt = 1'd0;
	assign ddr3_dq = {64{1'bz}};
	assign ddr3_dqs_p = {8{1'bz}};
	assign ddr3_dqs_n = {8{1'bz}};

	/* The stub reads none of its inputs. */
	wire unused_ok = &{1'b0,
		clk, rst_n, sys_clk, sys_rst_n, s_awaddr, s_awlen, s_awsize, s_awburst, s_awcache,
		s_awprot, s_awvalid, s_wdata, s_wstrb, s_wlast, s_wvalid, s_bready, s_araddr, s_arlen,
		s_arsize, s_arburst, s_arcache, s_arprot, s_arvalid, s_rready, ddr3_dq, ddr3_dqs_p,
		ddr3_dqs_n};
endmodule

`default_nettype wire
